                              IN gctSIZE_T Offset, OUT gctPHYS_ADDR_T *PhysicalAddress)
{
    printk(KERN_INFO "FUNC_ENTRY: Entering function gckVIDMEM_NODE_GetCPUPhysical at %s:%d\n", __FILE__, __LINE__);
